struct app_state { int count; const char *filter; };
enum act_kind { ACT_INC, ACT_SET_FILTER };
static struct app_state reduce(const struct app_state *s, const struct act *a)
{
    struct app_state next = *s;                 /* copy - never mutate in place */
    switch (a->kind) {
    case ACT_INC:        next.count++; break;
    case ACT_SET_FILTER: next.filter = a->text; break;
    }
    return next;
}
